# Lesson 1, parts 3 and 4: summaries and practice on everything up to the Forward sheet, then homework and sources.
# Figures of the worked exercises are checked here, so a typo stops the build.
assert 2400000 - 1600000 == 800000 and round(800000 * (3.55 - 3.70)) == -120000 and round(2400000 * 0.15) == 360000 and round(1600000 * 0.15) == 240000
assert round(2400000 * (3.55 - 3.70)) - round(1600000 * (3.55 - 3.70)) == -120000
assert 1000 * (72 - 80) == -8000 and 1000 * (80 - 72) == 8000
assert 1000 * 72 - (-8000) == 80000 == 1000 * 80
assert round(800000 * 3.85) == 3080000 and round(800000 * (3.85 - 3.62)) == 184000 and 3080000 - 184000 == 2896000
assert 250000 * 0.04 == 10000 and 700000 - 950000 == -250000 and 2000 * (90 - 84) == 12000
assert round(200000 * 3.50) == 700000 and round(200000 * (3.50 - 3.70)) == -40000
# summary 2: Dana buys (Long) a Forward on 500,000 dollars at K = 3.55, and the rate at payment is 3.80
assert round(500000 * 3.80) == 1900000 and round(500000 * (3.80 - 3.55)) == 125000 and 1900000 - 125000 == 1775000 == round(500000 * 3.55)
# summary 1 and 3: the figures quoted from part 1
assert 1500 - 1000 == 500 and 500000 * 0.01 == 5000 and 1000000 - 900000 == 100000
assert 1950000 - round(500000 * 3.80) == 50000 and 200000 - 50000 == 150000 and 300000 - 100000 == 200000
# the cartoon of sheet 1: one agora on a million dollars
assert round(1000000 * 0.01) == 10000

# ================================================================ part 3
opener(3, 'סיכום ותרגול', 'שאלת החלק: האם אתם יודעים לעשות את זה לבד?',
       ['שלושה שקפי סיכום: מושגים, נוסחאות והחלטות', 'שאלות רב ברירה ומקרים, עם הסבר בשלבים', 'תרגילי אקסל קטנים בתוך השקפים', 'בכל תרגיל: רמז, תזכורת נוסחה, פתרון חלקי ופתרון מלא'], 45)

S('s-sumA', 'סיכום 1: מושגים', 'סיכום 1: המושגים של המפגש',
  '<p class="lead g-lead">' + TX('נסו להגדיר כל מושג בעצמכם, ורק אז לחצו: ההגדרה והדוגמה יופיעו.') + '</p>'
  + _G_RT(['מושג', 'בפשטות', 'דוגמה מהשיעור, במספרים'], [
      ['נגזר (Derivative)', 'חוזה ששוויו נגזר ממחיר של נכס אחר', 'שובר טיסה: זכות לקנות כרטיס ב-1,000 דולר. הכרטיס ב-1,500: השובר שווה $1,500 − 1,000 = 500$'],
      ['נכס בסיס (Underlying)', 'הדבר שעל מחירו נכתב החוזה', 'כרטיס הטיסה, הדולר, חבית נפט'],
      ['מחיר מיידי (Spot price)', 'מסומן $S$: המחיר לעסקה שמתבצעת עכשיו', 'הדולר נסחר היום ב-3.50: $S_{0} = 3.50$. בפקיעה: $S_{T}$'],
      ['פרמיה (Premium)', 'המחיר שמשלמים היום על זכות', '50 דולר על השובר, והם לא חוזרים'],
      ['גידור (Hedging)', 'הקטנת סיכון שכבר קיים', 'דנה קובעת היום את השער לתשלום של 500,000 דולר'],
      ['ספקולציה (Speculation)', 'נטילת סיכון כדי להרוויח משינוי מחיר', 'משקיע בלי שום צורך בנפט קונה חוזה על נפט'],
      ['חיסכון בעלויות', 'אותה חשיפה למחיר, בלי להחזיק את הנכס', 'קרן קונה חוזה על נפט, ולא שוכרת מחסן לחביות'],
      ['חשיפה (Exposure)', 'כמה התוצאה זזה כשמחיר זז', 'אצל דנה: $500,000 × 0.01 = 5,000$ ש״ח לכל אגורה בשער'],
      ['חשיפה נטו (Net exposure)', 'הכנסות פחות הוצאות, באותו מטבע ובאותו מועד', '$1,000,000 − 900,000 = 100,000$ דולר'],
      ['גידור טבעי (Natural hedge)', 'הכנסות והוצאות באותו מטבע שמקזזות זו את זו', '900,000 דולר מתוך המיליון מתקזזים בלי שום חוזה']], cls='g-sum'), kick='חלק 3 · סיכום')

S('s-sumB', 'סיכום 2: חוזה אקדמה', 'סיכום 2: חוזה אקדמה (Forward) בנוסחאות',
  '<div class="row top g-two"><div class="col g-c1">'
  + TABLE(['צד', 'מה התחייב', 'תזרים בפקיעה (Payoff)', 'דוגמה: $K = 100$, $S_{T} = 110$'], [
      ['קונה (Long)', 'לקנות ב-$K$', '$S_{T} − K$', '$110 − 100 = 10$'],
      ['מוכר (Short)', 'למכור ב-$K$', '$K − S_{T}$', '$100 − 110 = −10$'],
      ['שניהם יחד', 'סכום אפס (Zero sum)', '$0$', '$10 + (−10) = 0$']], 'g-pay')
  + '<div class="card g-imp"><b class="ct">יבואנית שקונה (Long) חוזה: העלות נטו קבועה</b><p>'
  + TX('דנה תשלם לספק 500,000 דולר. היא קנתה (Long) חוזה אקדמה על 500,000 דולר, ב-$K = 3.55$. ביום התשלום $S_{T} = 3.80$.') + '</p>'
  + TABLES(['מה מחשבים', 'כמה', 'איך'], [
      ['תשלום לספק', '1,900,000 ש״ח', '$500,000 × 3.80$'],
      ['תוצאת החוזה (Long)', '125,000 ש״ח', '$500,000 × (3.80 − 3.55)$'],
      ['עלות נטו', '1,775,000 ש״ח', '$1,900,000 − 125,000$']])
  + BAND('dg', 'בכל שער, העלות נטו היא כמות כפול $K$: $500,000 × 3.55 = 1,775,000$.', 4) + '</div></div><div class="col g-c2">'
  + '<div class="card g-sig"><b class="ct">הסימנים</b><p>' + TX('$K$: מחיר החוזה, שנקבע היום. $T$: מועד הפקיעה. $S_{T}$: מחיר נכס הבסיס בשוק במועד הפקיעה.') + '</p><div class="demo">'
  + TX('<b>בכסף:</b> כופלים בכמות. חוזה על 1,000 חביות, ו-$S_{T} − K = 10$: $1,000 × 10 = 10,000$ דולר.') + '</div></div>'
  + TABLE(['', 'חוזה אקדמה (Forward)', 'חוזה עתידי (Futures)'], [
      ['היכן', 'מול בנק, מעבר לדלפק', 'בבורסה'],
      ['תנאים', 'מותאמים', 'אחידים'],
      ['התחשבנות', 'בפקיעה', 'בכל יום'],
      ['פרמיה', 'אין', 'אין, יש ביטחונות (Margin)']], 'g-ff')
  + MEME('seesaw', 'Long ו-Short על אותה נדנדה', 'אחד עולה ב-10, השני יורד ב-10. ביחד: אפס') + '</div></div>', kick='חלק 3 · סיכום')

S('s-sumC', 'סיכום 3: מתי לגדר', 'סיכום 3: מוסיף ערך, מיותר או מסוכן?',
  '<p class="lead g-lead">' + TX('בכל שורה: קראו את המצב ואת הדוגמה, החליטו בעצמכם, ורק אז לחצו.') + '</p>'
  + _G_RT(['מצב', 'דוגמה מהמקרים', 'החלטה', 'למה'], [
      ['חשיפה נטו גדולה, וחוזה בגודל החשיפה', 'דנה: תשלום של 500,000 דולר. דולר ב-3.80 מקטין את הרווח מ-200,000 ל-50,000 ש״ח', '<b>מוסיף ערך</b>', 'העסק חוזר להרוויח מהמוצר, לא מהשער'],
      ['חשיפה נטו אפס', 'הכנסות של 1,000,000 דולר והוצאות של 1,000,000 דולר, באותו חודש', '<b>מיותר</b>', 'הגידור הטבעי כבר עושה את העבודה'],
      ['חשיפה קטנה, וגידור יקר ממנה', 'סיכון של כ-1,000 ש״ח, מול עלות של 3,000 ש״ח לחוזה', '<b>מיותר</b>', 'העלות הוודאית גדולה מהסיכון'],
      ['חוזה גדול מהחשיפה נטו', 'תשלום של 100,000 דולר, וחוזה על 300,000 דולר: עודף של 200,000', '<b>מסוכן</b>', 'החלק העודף הוא הימור, לא גידור']], keep=2, cls='g-dec')
  + '<div class="row g-end">' + BAND('note', 'הסדר תמיד זהה: מחשבים חשיפה נטו, בודקים את גודלה ביחס לרווח ולעלות, ורק אז בוחרים חוזה בגודל המתאים.', 5)
  + TOON('seesaw', 'גידור טוב נראה משעמם: הרווח פשוט לא זז.') + '</div>', kick='חלק 3 · סיכום')

MCS('m-p1', 'תרגול: נגזר ומניעים', 'תרגול: נגזר, נכס בסיס ומניעים', [
    mc('qa1', 'רשת בתי קפה חותמת היום על חוזה: בעוד 3 חודשים היא תקנה 2,000 ק״ג פולי קפה ב-30 ש״ח לק״ג, יהיה מחיר הקפה בשוק אשר יהיה. <b>נדרש:</b> מהו נכס הבסיס (Underlying) של החוזה?',
       ['פולי הקפה', 'החוזה עצמו', 'הבורסה שבה נסחר החוזה', 'הכסף שעובר בפקיעה'], 0, 'נכס הבסיס הוא הדבר שעל מחירו נכתב החוזה: הקפה. החוזה עצמו הוא הנגזר.',
       rem='נכס בסיס = הדבר שעל מחירו נכתב החוזה. נגזר = החוזה, ששוויו נגזר ממחיר נכס הבסיס.'),
    mc('qa2', 'אותה רשת קונה קפה בכל חודש. המחירים בתפריט כבר מודפסים, ולכן אם הקפה יתייקר, הרווח שלה יקטן. היא נכנסת לחוזה שקובע היום את מחיר הקפה. <b>נדרש:</b> מה המניע שלה?',
       ['גידור (Hedging)', 'ספקולציה (Speculation)', 'חיסכון בעלויות', 'גידור טבעי (Natural hedge)'], 0, 'יש לה חשיפה קיימת: הקפה הוא הוצאה. החוזה מקטין אותה.',
       rem='גידור = הקטנת סיכון שכבר קיים. ספקולציה = נטילת סיכון כדי להרוויח משינוי מחיר.'),
    mc('qa3', 'בצד השני של החוזה צריך לעמוד מי שמתחייב למכור לרשת 2,000 ק״ג קפה בעוד 3 חודשים, ב-30 ש״ח לק״ג. <b>נדרש:</b> מי מתאים לעמוד בצד השני?',
       ['מגדל קפה שחושש מירידת המחיר', 'רשת בתי קפה מתחרה', 'לקוח של בית הקפה', 'הספק של הכוסות'], 0, 'המגדל מוכר קפה, ולכן חשוף בכיוון ההפוך. גם ספקולנט יכול לעמוד שם.',
       rem='בצד השני עומד מי שחשוף בכיוון ההפוך, או ספקולנט שמוכן לשאת בסיכון.')])

_G_CASE('c-p1', 'תרגול: למה לא לקנות מטילים?',
        'קרן השקעות רוצה חשיפה למחיר הזהב לשנה: שהתיק ירוויח אם הזהב יתייקר, ויפסיד אם יוזל. לקרן אין שום עסק שקשור בזהב. אפשרות א: לקנות מטילי זהב, לאחסן אותם בכספת ולבטח אותם. אפשרות ב: להיכנס לחוזה על מחיר הזהב, בלי להחזיק מטיל אחד.',
        '<b>נדרש:</b> למה שהקרן תבחר באפשרות ב ולא באפשרות א?', ['חיסכון בעלויות', 'גידור (Hedging)', 'ספקולציה (Speculation)'], 0, 'אותה חשיפה למחיר, בלי כספת, ביטוח והובלה.',
        ST(1, TX('<b>שלב 1, מה הקרן רוצה?</b> חשיפה למחיר הזהב. היא לא צריכה את המטילים עצמם.'), 'p', 'sp')
        + TABLES(['', 'א: מטילים בכספת', 'ב: חוזה על מחיר הזהב'], [
            ['<b>מרוויחה כשהזהב עולה?</b>', 'כן', 'כן, החוזה נגזר מהמחיר'],
            ['<b>כספת, ביטוח, הובלה?</b>', 'כן, בתשלום', 'לא צריך'],
            ['<b>מקטינה סיכון קיים?</b>', 'לא', 'לא']], cls='g-ab', start=2)
        + ST(5, TX('<b>שלב 2, למה לא גידור?</b> לקרן אין חשיפה קיימת לזהב שהיא מקטינה.'), 'p', 'sp')
        + ST(6, TX('<b>שלב 3, למה לא ספקולציה?</b> ההימור על הזהב קיים בשתי האפשרויות באותה מידה. ההבדל ביניהן הוא רק בעלות.'), 'p', 'sp')
        + ST(7, TX('<b>מסקנה:</b> חיסכון בעלויות. החוזה נותן את אותה חשיפה, בזול.'), cls='band ans'),
        rem='גידור = הקטנת סיכון שכבר קיים. ספקולציה = נטילת סיכון כדי להרוויח משינוי מחיר. חיסכון בעלויות = אותה חשיפה, בעלות נמוכה יותר.')

